  { id: 1200, category: "tsushin", source: "vocab-supplementary", furi: "まるちもーどふぁいばー", jp: "マルチモードファイバー", type: "vocab", id_text: "Fiber optik multi-mode", desc: "MMF berdiameter inti 50 atau 62.5μm, umum dipakai untuk kabel LAN dalam gedung." },
  { id: 1201, category: "tsushin", source: "vocab-exam", furi: "えすしーこねくた", jp: "SCコネクタ", type: "vocab", id_text: "Konektor fiber optik", desc: "Konektor push-pull untuk sambungan ONU. Mudah dipasang dan dilepas dengan satu" },
  { id: 1202, category: "tsushin", source: "vocab-exam", furi: "えるしーこねくた", jp: "LCコネクタ", type: "vocab", id_text: "Konektor fiber optik", desc: "Lebih kecil dari SC, memungkinkan kepadatan tinggi. Banyak dipakai di switch" },
  { id: 1203, category: "tsushin", source: "vocab-supplementary", furi: "えすてぃーこねくた", jp: "STコネクタ", type: "vocab", id_text: "Konektor fiber optik", desc: "Konektor fiber yang dikunci dengan memutar seperti bayonet; dahulu umum di" },
  { id: 1204, category: "tsushin", source: "vocab-supplementary", furi: "はんしゃそんしつ", jp: "反射損失", type: "vocab", id_text: "Rugi daya akibat", desc: "Nilai refleksi tinggi pada sambungan konektor; terlihat sebagai lonjakan pada" },
  { id: 1205, category: "tsushin", source: "vocab-supplementary", furi: "そうにゅうそんしつ", jp: "挿入損失", type: "vocab", id_text: "Rugi sisip pada", desc: "Kehilangan daya saat sinyal melewati konektor atau sambungan fusion." },
  { id: 1206, category: "tsushin", source: "vocab-supplementary", furi: "でっどぞーん", jp: "デッドゾーン", type: "vocab", id_text: "Zona buta OTDR", desc: "Area dalam dead zone OTDR yang tidak dapat diukur; rugi tepat setelah konektor" },
  { id: 1207, category: "tsushin", source: "vocab-supplementary", furi: "ぱっちぱねる", jp: "パッチパネル", type: "vocab", id_text: "Panel distribusi", desc: "Tempat kabel LAN dari berbagai titik disambungkan untuk merapikan kabel menuju" },
  { id: 1208, category: "tsushin", source: "vocab-supplementary", furi: "えすてぃーぴーけーぶる", jp: "STPケーブル", type: "vocab", id_text: "Kabel twisted pair", desc: "STP memiliki pelindung yang memblokir gangguan elektromagnetik, cocok untuk" },
  { id: 1209, category: "tsushin", source: "vocab-exam", furi: "つうしんらっく", jp: "通信ラック", type: "vocab", id_text: "Rak telekomunikasi 19", desc: "Rak standar 19 inci untuk switch, patch panel, dan server di ruang" },
  { id: 1210, category: "tsushin", source: "vocab-exam", furi: "つうしんきゃびねっと", jp: "通信キャビネット", type: "vocab", id_text: "Kabinet perangkat", desc: "Kabinet tertutup untuk perangkat telekomunikasi.\nPermasangan luar ruangan:" },
  { id: 1211, category: "tsushin", source: "vocab-supplementary", furi: "あいでぃーえふ（ちゅうかんはいせんばん）", jp: "IDF（中間配線盤）", type: "vocab", id_text: "Panel distribusi kabel", desc: "Di gedung besar, kabel trunk dari MDF didistribusikan via IDF ke terminal di" },
  { id: 1212, category: "tsushin", source: "vocab-supplementary", furi: "せっちたんしばん", jp: "接地端子盤", type: "vocab", id_text: "Panel terminal grounding", desc: "Kabel grounding semua perangkat komunikasi dikumpulkan di sini untuk" },
  { id: 1213, category: "tsushin", source: "vocab-exam", furi: "ほあんき", jp: "保安器", type: "vocab", id_text: "Pelindung jalur masuk", desc: "Dipasang di titik masuk kabel untuk melindungi peralatan komunikasi dari" },
  { id: 1214, category: "tsushin", source: "vocab-supplementary", furi: "たんしだい", jp: "端子台", type: "vocab", id_text: "Terminal block / blok", desc: "Beberapa kabel dikencangkan dengan sekrup pada blok ini untuk membagi dan" },
  { id: 1215, category: "tsushin", source: "vocab-general", furi: "せいたん", jp: "成端", type: "vocab", id_text: "Terminasi ujung kabel", desc: "Pekerjaan pengakhiran ujung kabel; untuk fiber meliputi pemasangan konektor dan", usage: "成端《せいたん》作業《さぎょう》を行《おこな》う（melaksanakan pekerjaan terminasi kabel）" },
  { id: 1216, category: "tsushin", source: "vocab-supplementary", furi: "しんせんたいしょう", jp: "心線対照", type: "vocab", id_text: "Identifikasi pasangan", desc: "Pemeriksaan untuk memastikan inti mana dalam kabel multi-core yang terhubung ke" },
  { id: 1217, category: "tsushin", source: "vocab-supplementary", furi: "ひかりけーぶるのまげはんけい", jp: "光ケーブルの曲げ半径", type: "vocab", id_text: "Radius tikungan minimum", desc: "Jika radius tikungan lebih kecil dari nilai minimum, rugi cahaya melonjak dan" },
  { id: 1218, category: "tsushin", source: "vocab-supplementary", furi: "かてごりーごいーけーぶる", jp: "Cat5eケーブル", type: "vocab", id_text: "Kabel UTP Cat5e, hingga", desc: "Kabel Cat5e mendukung Gigabit Ethernet (1000BASE-T), banyak digunakan untuk LAN" },
  { id: 1219, category: "tsushin", source: "vocab-supplementary", furi: "かてごりーろくけーぶる", jp: "Cat6ケーブル", type: "vocab", id_text: "Kabel UTP Cat6, hingga", desc: "Lebih tahan noise frekuensi tinggi dari Cat5e; mampu mendukung 10GbE pada jarak" },
  { id: 1220, category: "tsushin", source: "vocab-supplementary", furi: "ひかりすぷりったー", jp: "光スプリッター", type: "vocab", id_text: "Pembagi sinyal optik", desc: "Dalam sistem PON, splitter optik membagi satu fiber menjadi jalur untuk banyak" },
  { id: 1221, category: "tsushin", source: "vocab-supplementary", furi: "ぽん（じゅどうひかりねっとわーく）", jp: "PON（受動光ネットワーク）", type: "vocab", id_text: "Passive Optical Network", desc: "Arsitektur jaringan fiber pasif yang menghubungkan OLT dan ONU melalui splitter" },
  { id: 1222, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "わくぐみあしば", jp: "枠組足場", id_text: "Scaffolding rangka (perancah pabrikasi)", desc: "例: 枠組足場は、建設工事で最も一般的に使われる仮設足場の一種です。→ Scaffolding rangka adalah jenis perancah sementara yang paling umum di proyek konstruksi. Terbuat dari panel baja pabrikasi yang dipasang vertikal dan horizontal." },
  { id: 1223, category: "anzen", source: "vocab-exam", furi: "たんかんあしば", jp: "単管足場", type: "vocab", id_text: "Scaffolding pipa tunggal", desc: "Scaffolding pipa baja disambung klem.\nFleksibel untuk berbagai bentuk bangunan.", usage: "単管足場《たんかんあしば》を組《く》む（memasang scaffolding pipa tunggal）" },
  { id: 1224, category: "anzen", source: "vocab-exam", furi: "くさびきんけつしきあしば", jp: "くさび緊結式足場", type: "vocab", id_text: "Scaffolding sistem baji", desc: "Scaffolding baji, dipasang dengan satu palu.\nLebih cepat dari tipe pipa tunggal.", usage: "足場《あしば》を組《く》む（memasang scaffolding）" },
  { id: 1225, category: "anzen", source: "vocab-exam", furi: "あんぜんねっと", jp: "安全ネット", type: "vocab", id_text: "Jaring pengaman", desc: "Jaring pengaman di bawah area kerja ketinggian.\nWajib di area risiko jatuh.", usage: "安全《あんぜん》ネットを設置《せっち》する（memasang jaring pengaman）" },
  { id: 1226, category: "anzen", source: "vocab-exam", furi: "てすり", jp: "手すり", type: "vocab", id_text: "Handrail / pagar pengaman", desc: "Pagar pengaman di tepi platform kerja.\nMinimal tinggi 85 cm — wajib dipasang.", usage: "手《て》すりを設置《せっち》する（memasang guardrail）" },
  { id: 1227, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "なかさん", jp: "中さん", id_text: "Mid-rail / rel tengah scaffolding", desc: "例: 手すりと幅木の間に中さんを取り付けて、作業員の転落を防ぎます。→ Mid-rail dipasang di antara guardrail atas dan toe board untuk mencegah pekerja tergelincir jatuh. Posisi sekitar 35–50 cm dari platform." },
  { id: 1228, category: "anzen", source: "vocab-general", type: "vocab", furi: "はばき", jp: "巾木", id_text: "Toe board / papan pengaman bawah", desc: "例: 巾木を足場の端に設置することで、工具や資材の落下を防げます。→ Toe board dipasang di bagian bawah tepi scaffolding untuk mencegah alat dan material jatuh ke bawah. Tinggi minimal 10 cm." },
  { id: 1229, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "しょうこうせつび", jp: "昇降設備", id_text: "Fasilitas naik-turun (tangga/stairway)", desc: "例: 足場には、作業員が安全に昇降できる昇降設備を設けることが義務です。→ Scaffolding wajib dilengkapi fasilitas naik-turun agar pekerja dapat mengakses ketinggian dengan aman. Termasuk tangga tetap dan tangga portable." },
  { id: 1230, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "さんそのうどけい", jp: "酸素濃度計", id_text: "Alat ukur kadar oksigen", desc: "例: 密閉空間に入る前に、酸素濃度計で酸素濃度が18%以上あることを確認します。→ Sebelum memasuki ruang tertutup, konfirmasi kadar oksigen minimal 18% dengan oksimeter. Kadar di bawah 18% = bahaya kekurangan oksigen." },
  { id: 1231, category: "anzen", source: "vocab-exam", furi: "りゅうかすいそ", jp: "硫化水素", type: "vocab", id_text: "Hidrogen sulfida (H₂S)", desc: "Gas beracun tak berwarna berbau telur busuk.\nBatas aman di bawah 10 ppm." },
  { id: 1232, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "ゆうがいがすけんちき", jp: "有害ガス検知器", id_text: "Detektor gas berbahaya", desc: "例: 密閉空間作業前に有害ガス検知器を使って、一酸化炭素や硫化水素の濃度を測ります。→ Sebelum kerja di ruang tertutup, ukur konsentrasi CO dan H₂S menggunakan detektor gas berbahaya. Wajib dilakukan sebelum pekerja masuk." },
  { id: 1233, category: "anzen", source: "vocab-exam", furi: "そうきますく", jp: "送気マスク", type: "vocab", id_text: "Respirator suplai udara", desc: "Masker dengan suplai udara dari luar.\nWajib di ruang oksigen rendah/bergas", usage: "送気《そうき》マスクを着用《ちゃくよう》する（memakai respirator suplai udara）" },
  { id: 1234, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "ろっくあうとたぐあうと", jp: "ロックアウト・タグアウト", id_text: "Lockout-Tagout (LOTO) — prosedur pengamanan energi", desc: "例: 設備のメンテナンス中は、ロックアウト・タグアウトを実施して誤作動を防ぎます。→ Saat perawatan alat, terapkan prosedur LOTO untuk mencegah mesin menyala tidak sengaja. Energi dikunci (lock) dan diberi tanda peringatan (tag)." },
  { id: 1235, category: "anzen", source: "vocab-exam", furi: "さぎょうしゅにんしゃ", jp: "作業主任者", type: "vocab", id_text: "Supervisor kerja resmi", desc: "Supervisor bersertifikat wajib untuk pekerjaan berbahaya tertentu." },
  { id: 1236, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "つーるぼっくすみーてぃんぐ", jp: "ツールボックスミーティング", id_text: "Toolbox meeting (TBM) / rapat singkat keselamatan", desc: "例: 毎朝の作業開始前にツールボックスミーティングで当日の危険ポイントを確認します。→ Setiap pagi sebelum kerja dimulai, bahaya hari itu dikonfirmasi bersama dalam toolbox meeting. Biasanya berlangsung 5–15 menit di lokasi kerja." },
  { id: 1237, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "あんぜんとうばん", jp: "安全当番", id_text: "Petugas keselamatan harian (giliran)", desc: "例: 安全当番は、当日の現場の安全状態を巡回して確認し、記録する役割を担います。→ Petugas keselamatan harian bertugas berkeliling mengecek dan mencatat kondisi keamanan lapangan. Dilakukan secara bergilir oleh anggota tim." },
  { id: 1238, category: "anzen", source: "vocab-exam", furi: "あんぜんぱとろーる", jp: "安全パトロール", type: "vocab", id_text: "Patroli keselamatan site", desc: "Pemeriksaan berkala oleh tim K3 untuk menemukan bahaya di site.", usage: "安全《あんぜん》パトロールを実施《じっし》する（melaksanakan patroli keselamatan）" },
  { id: 1239, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "さぎょうてじゅんしょ", jp: "作業手順書", id_text: "Manual prosedur kerja (SOP)", desc: "例: 作業手順書には、作業の流れ・使用機材・注意事項・緊急時の対応が記載されています。→ Manual prosedur kerja memuat alur pekerjaan, peralatan yang digunakan, peringatan keselamatan, dan langkah darurat." },
  { id: 1240, category: "anzen", source: "vocab-exam", furi: "ついらくせいしようきぐ", jp: "墜落制止用器具", type: "vocab", id_text: "Harness pencegah jatuh", desc: "Wajib dipakai di ketinggian ≥2 meter.\nTipe full-harness diwajibkan sejak 2019.", usage: "ハーネスを装着《そうちゃく》する（memakai harness pencegah jatuh）" },
  { id: 1241, category: "anzen", source: "vocab-exam", furi: "ひらいらっか", jp: "飛来・落下", type: "vocab", id_text: "Bahaya benda jatuh atas", desc: "Benda jatuh/terbang saat kerja di atas — akses bawah wajib ditutup." },
  { id: 1242, category: "anzen", source: "vocab-exam", furi: "ねっちゅうしょう", jp: "熱中症", type: "vocab", id_text: "Serangan panas", desc: "Kondisi berbahaya akibat suhu terlalu panas.\nCegah: air dan suplemen garam" },
  { id: 1243, category: "anzen", source: "vocab-exam", furi: "ふんじん", jp: "粉じん", type: "vocab", id_text: "Debu berbahaya / dust", desc: "Debu halus dari pemotongan material.\nWajib pakai masker anti-debu di lokasi" },
  { id: 1244, category: "anzen", source: "vocab-exam", furi: "りすくあせすめんと", jp: "リスクアセスメント", type: "vocab", id_text: "Penilaian risiko kerja", desc: "Identifikasi dan evaluasi bahaya sebelum bekerja.\nHasil harus didokumentasikan.", usage: "リスクアセスメントを実施《じっし》する（melakukan penilaian risiko）" },
  { id: 1245, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "ひやりはっと", jp: "ヒヤリハット", id_text: "Near miss / hampir celaka", desc: "例: ヒヤリハット報告書を提出・共有することで、重大事故の予防につながります。→ Melaporkan dan berbagi near miss membantu mencegah kecelakaan serius." },
  { id: 1246, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "きけんよちくんれん", jp: "KYT（危険予知訓練）", id_text: "Pelatihan prediksi bahaya (KYT)", desc: "例: KYTでは、作業前にチーム全員で現場の危険箇所を指摘し合い、対策を決めます。→ Dalam KYT, seluruh tim saling menunjukkan titik berbahaya di lokasi sebelum kerja dimulai dan menetapkan tindakan pencegahan." },
  { id: 1247, category: "doboku_haisui", source: "vocab-supplementary", furi: "こうかんくい", jp: "鋼管杭", type: "vocab", id_text: "Tiang pancang pipa baja", desc: "Tiang pipa baja pracetak dipancang hingga lapisan pendukung.\nKuat menahan beban", usage: "鋼管杭《こうかんくい》を打《う》ち込《こ》む（memancang tiang pipa baja）" },
  { id: 1248, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ピーシーぐい", jp: "PC杭", id_text: "Tiang pancang beton prategang", desc: "例: PC杭はプレストレストコンクリート製の既製杭である。→ PC杭 adalah tiang pracetak dari beton prategang (prestressed concrete). Digunakan sebagai pondasi dalam di tanah berbatu." },
  { id: 1249, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ピーエイチシーぐい", jp: "PHC杭", id_text: "Tiang beton prategang tegangan tinggi", desc: "例: PHC杭はPC杭より強度が高く、大型建築物の基礎に使われる。→ PHC杭 memiliki kekuatan lebih tinggi dari PC杭, dipakai untuk pondasi bangunan besar. PHC = Pretensioned spun High strength Concrete." },
  { id: 1250, category: "sekou", source: "vocab-exam", furi: "しーとぱいる", jp: "シートパイル", type: "vocab", id_text: "Sheet pile / turap baja", desc: "Turap baja dipancang berurutan mencegah tanah longsor.", usage: "シートパイルを打《う》ち込《こ》む（memancang sheet pile）" },
  { id: 1251, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "あーすあんかー", jp: "アースアンカー", type: "vocab", id_text: "Angkur tanah / ground", desc: "Kabel atau batang baja yang ditanam ke tanah keras untuk menahan gaya tarik", usage: "アースアンカーを打《う》つ（memasang ground anchor）" },
  { id: 1252, category: "kenchiku_shiage", source: "vocab-exam", furi: "あすふぁるとぼうすい", jp: "アスファルト防水", type: "vocab", id_text: "Waterproofing aspal", desc: "Sistem waterproofing menggunakan lembaran aspal untuk atap beton.", usage: "アスファルト防水《ぼうすい》を施工《せこう》する（mengerjakan waterproofing aspal）" },
  { id: 1253, category: "kenchiku_shiage", source: "vocab-exam", furi: "しーとぼうすい", jp: "シート防水", type: "vocab", id_text: "Waterproofing lembaran", desc: "Lapisan kedap air dari lembaran karet sintetis atau PVC.", usage: "シート防水《ぼうすい》を施工《せこう》する（mengerjakan sheet waterproofing）" },
  { id: 1254, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "とまくぼうすい", jp: "塗膜防水", type: "vocab", id_text: "Waterproofing lapisan", desc: "Metode waterproofing dengan mengoleskan material cair (uretan) menggunakan", usage: "塗膜《とまく》防水《ぼうすい》を施工《せこう》する（mengaplikasikan coating waterproofing）" },
  { id: 1255, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "しつじゅんようじょう", jp: "湿潤養生", id_text: "Perawatan beton dengan pembasahan", desc: "例: 打設後のコンクリートは湿潤養生を行い、乾燥によるクラックを防ぐ。→ Setelah pengecoran, beton dirawat dengan menjaga kelembaban (湿潤養生) untuk mencegah retak akibat pengeringan terlalu cepat." },
  { id: 1256, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "じょうきようじょう", jp: "蒸気養生", id_text: "Perawatan beton dengan uap panas", desc: "例: プレキャスト製品は蒸気養生で短期間に強度を出す。→ Produk precast (pracetak) menggunakan steam curing (蒸気養生) untuk mencapai kekuatan awal dalam waktu singkat. Suhu dijaga sekitar 60–80°C." },
  { id: 1257, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ひまくようじょう", jp: "被膜養生", id_text: "Perawatan beton dengan lapisan membran", desc: "例: 被膜養生剤を散布して、コンクリート表面から水分が蒸発するのを防ぐ。→ Agen membran disemprotkan ke permukaan beton untuk mencegah penguapan air. Metode ini tidak memerlukan penyiraman berkala." },
  { id: 1258, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "すぺーさー", jp: "スペーサー", type: "vocab", id_text: "Penyangga tulangan /", desc: "Benda kecil dari mortar atau plastik yang diletakkan di bawah tulangan untuk", usage: "スペーサーを敷《し》く（meletakkan beton tahu）" },
  { id: 1259, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "うちつぎめ", jp: "打ち継ぎ目", id_text: "Sambungan pengecoran beton", desc: "例: 打ち継ぎ目は構造的弱点になりやすいため、位置を適切に設けること。→ Construction joint (打ち継ぎ目) adalah batas antara pengecoran lama dan baru, yang rawan menjadi titik lemah struktural jika tidak dikerjakan dengan benar." },
  { id: 1260, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "せぱれーたー", jp: "セパレーター", type: "vocab", id_text: "Pengikat jarak bekisting", desc: "Pengikat logam yang menjaga jarak antar dua sisi bekisting agar tetap konsisten", usage: "セパレーターを取《と》り付《つ》ける（memasang form tie）" },
  { id: 1261, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "かたわくりけいざい", jp: "型枠離型剤", type: "vocab", id_text: "Agen pelepas bekisting", desc: "Zat yang dioleskan ke permukaan bekisting sebelum pengecoran agar bekisting", usage: "離型剤《りけいざい》を塗布《とふ》する（mengoleskan release agent）" },
  { id: 1262, category: "kenchiku_kutai", source: "vocab-exam", furi: "すらんぷしけん", jp: "スランプ試験", type: "vocab", id_text: "Uji slump beton", desc: "Tes lapangan untuk mengecek konsistensi beton segar sebelum cor.", usage: "スランプ試験《しけん》を実施《じっし》する（melakukan slump test）" },
  { id: 1263, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ぶりーでぃんぐ", jp: "ブリーディング", id_text: "Bleeding (naiknya air ke permukaan beton)", desc: "例: ブリーディングが過剰だと表面強度が低下し、クラックの原因となる。→ Bleeding adalah fenomena air naik ke permukaan beton segar akibat gravitasi. Jika berlebihan, permukaan beton menjadi lemah dan mudah retak." },
  { id: 1264, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "じゃんか", jp: "ジャンカ", type: "vocab", id_text: "Sarang lebah / cacat", desc: "Cacat pada beton berupa rongga yang terlihat di permukaan, akibat pemadatan" },
  { id: 1265, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "くらっく", jp: "クラック", id_text: "Retak / retakan pada beton", desc: "例: 乾燥収縮や過大な応力によってコンクリートにクラックが生じる。→ Retakan (クラック) pada beton bisa disebabkan oleh penyusutan pengeringan, pembebanan berlebih, atau perawatan yang tidak tepat." },
  { id: 1266, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "てっきんたんさき", jp: "鉄筋探査機", type: "vocab", id_text: "Alat deteksi tulangan", desc: "Alat yang menggunakan gelombang elektromagnetik untuk mendeteksi posisi dan", usage: "鉄筋探査機《てっきんたんさき》で調査《ちょうさ》する（menginspeksi dengan rebar detector）" },
  { id: 1267, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "べーすぷれーと", jp: "ベースプレート", type: "vocab", id_text: "Pelat dasar kolom baja", desc: "Pelat baja yang dipasang di bawah kolom baja, disambungkan ke pondasi beton", usage: "ベースプレートを据《す》え付《つ》ける（memasang base plate）" },
  { id: 1268, category: "sekou", source: "vocab-exam", furi: "くいうちき", jp: "杭打ち機", type: "vocab", id_text: "Mesin pemancang tiang", desc: "Mesin (pile driver) untuk memancang tiang ke kedalaman yang ditentukan.", usage: "杭《くい》を打《う》つ（memancang tiang）" },
  { id: 1269, category: "doboku_haisui", source: "vocab-supplementary", furi: "えきじょうか", jp: "液状化", type: "vocab", id_text: "Likuefaksi tanah", desc: "Tanah berpasir jenuh air berperilaku seperti cairan saat gempa.\nStruktur di" },
  { id: 1270, category: "doboku_haisui", source: "vocab-supplementary", furi: "じたいりょく", jp: "地耐力", type: "vocab", id_text: "Daya dukung tanah", desc: "Kemampuan tanah menahan beban bangunan di atasnya.\nDiukur melalui uji N-value" },
  { id: 1271, category: "kenchiku_kutai", source: "vocab-supplementary", furi: "あんかーぼると", jp: "アンカーボルト", type: "vocab", id_text: "Baut angkur / anchor bolt", desc: "Baut yang ditanam di pondasi beton untuk mengikat base plate kolom baja.", usage: "アンカーボルトを埋《う》め込《こ》む（menanam anchor bolt）" },
  { id: 1272, category: "kenchiku_shiage", source: "vocab-exam", furi: "せっこうボード", jp: "石膏ボード", type: "vocab", id_text: "Papan gipsum", desc: "Papan gipsum untuk finishing dinding dalam dan plafon; ringan, tahan api.", usage: "石膏《せっこう》ボードを張《は》る（memasang papan gipsum）" },
  { id: 1273, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "けいりょうてっこつしたじ", jp: "軽量鉄骨下地", type: "vocab", id_text: "Rangka baja ringan LGS", desc: "Rangka dari baja ringan (ランナー + スタッド) yang menjadi substrat dinding/plafon", usage: "軽量鉄骨下地《けいりょうてっこつしたじ》を組《く》む（memasang rangka LGS）" },
  { id: 1274, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "てんじょうしたじ", jp: "天井下地", type: "vocab", id_text: "Rangka substrat plafon", desc: "Rangka plafon terdiri dari penggantung (野縁受《のぶちう》け) dan besi furring (野縁《のぶち》),", usage: "天井下地《てんじょうしたじ》を組《く》む（memasang rangka plafon）" },
  { id: 1275, category: "setsubi_kougu", source: "vocab-exam", furi: "システムてんじょう", jp: "システム天井", type: "vocab", id_text: "Plafon sistem /", desc: "Plafon modular yang mengintegrasikan pencahayaan, AC, dan peralatan kebakaran" },
  { id: 1276, category: "denki", source: "vocab-supplementary", furi: "フリーアクセスフロア", jp: "フリーアクセスフロア", type: "vocab", id_text: "Raised access floor /", desc: "Struktur lantai ganda yang memungkinkan kabel listrik dan LAN diatur bebas di" },
  { id: 1277, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ALCパネル", jp: "ALCパネル", id_text: "Panel beton ringan otoklaf (ALC)", desc: "例: ALCパネルは軽量で断熱性・耐火性に優れ、外壁や床・屋根に使用される。→ Panel ALC (Autoclaved Lightweight Concrete) sangat ringan, memiliki sifat insulasi panas dan tahan api yang baik, digunakan untuk dinding luar, lantai, dan" },
  { id: 1278, category: "sekou", source: "vocab-exam", furi: "カーテンウォール", jp: "カーテンウォール", type: "vocab", id_text: "Dinding tirai eksterior", desc: "Dinding luar non-struktural gedung tinggi — tidak menanggung beban." },
  { id: 1279, category: "sekou", source: "vocab-exam", furi: "サイディング", jp: "サイディング", type: "vocab", id_text: "Pelapis dinding eksterior", desc: "Penutup dinding luar bangunan.\nJenis: keramik (paling umum), logam, dan kayu.", usage: "サイディングを張《は》る（memasang siding）" },
  { id: 1280, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "コーキング", jp: "コーキング", id_text: "Caulking / pengisian celah sambungan", desc: "例: サイディングのパネル継ぎ目にコーキング材を充填して防水性を確保する。→ Material caulking diisikan pada celah sambungan antar panel siding untuk memastikan ketahanan air." },
  { id: 1281, category: "sekou", source: "vocab-exam", furi: "プライマー", jp: "プライマー", type: "vocab", id_text: "Primer / lapisan dasar", desc: "Lapisan dasar sebelum aplikasi sealant untuk meningkatkan daya rekat.", usage: "プライマーを塗布《とふ》する（mengoleskan primer）" },
  { id: 1282, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "バックアップざい", jp: "バックアップ材", id_text: "Backer rod / pengisi belakang sealant", desc: "例: 目地が深い場合はバックアップ材を入れてシーリングの厚みを適切に調整する。→ Jika celah terlalu dalam, backer rod (biasanya busa polyethylene bulat)" },
  { id: 1283, category: "kenchiku_shiage", source: "vocab-exam", furi: "ぼうすいシート", jp: "防水シート", type: "vocab", id_text: "Membran waterproof", desc: "Lembaran waterproof di bawah penutup atap, mencegah rembesan air hujan masuk.", usage: "防水《ぼうすい》シートを敷《し》く（menggelar membran waterproof）" },
  { id: 1284, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "みずきり", jp: "水切り", id_text: "Flashing / talang pengarah air hujan", desc: "例: 外壁の最下部に水切りを取り付けて、雨水が壁内部へ回り込まないようにする。→ Flashing dipasang di bagian bawah dinding luar untuk mengalirkan air hujan menjauhi struktur bangunan." },
  { id: 1285, category: "kenchiku_shiage", source: "vocab-exam", furi: "めじ", jp: "目地", type: "vocab", id_text: "Nat sambungan tile", desc: "Celah antara tile yang diisi material nat semen setelah pemasangan.", usage: "目地《めじ》を詰《つ》める（mengisi nat）" },
  { id: 1286, category: "kenchiku_shiage", source: "vocab-exam", furi: "モルタル", jp: "モルタル", type: "vocab", id_text: "Mortar semen-pasir", desc: "Campuran semen dan pasir sebagai dasar (leveling) sebelum tile dipasang.", usage: "モルタルを塗《ぬ》る（mengoleskan mortar）" },
  { id: 1287, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "ふきつけとそう", jp: "吹付け塗装", type: "vocab", id_text: "Pengecatan semprot /", desc: "Metode pengecatan menggunakan semprotan udara bertekanan untuk menghasilkan", usage: "吹付《ふきつ》け塗装《とそう》する（melakukan spray painting）" },
  { id: 1288, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ビニルゆかシート", jp: "ビニル床シート", id_text: "Lembaran lantai vinil", desc: "例: トイレや厨房などの水まわりにはビニル床シートが多く使用される。→ Lembaran lantai vinil banyak dipakai di toilet dan dapur karena tahan air, mudah dibersihkan, dan relatif mudah dipasang." },
  { id: 1289, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ちょうじゃくシート", jp: "長尺シート", id_text: "Long sheet: lembaran lantai panjang minim sambung", desc: "例: 廊下や通路に長尺シートを施工すると継ぎ目が少なく衛生的に管理できる。→ Long sheet banyak dipakai di koridor dan area publik karena sambungan sedikit sehingga mudah dijaga kebersihannya." },
  { id: 1290, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "したじしょり", jp: "下地処理", type: "vocab", id_text: "Persiapan substrat", desc: "Pembersihan substrat dari kotoran, cat lama, dan karat sebelum pengecatan atau", usage: "下地処理《したじしょり》する（melakukan surface preparation）" },
  { id: 1291, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "かべクロス", jp: "壁クロス", type: "vocab", id_text: "Wallpaper vinil /", desc: "Material pelapis dinding berbahan vinil yang ditempel pada papan gipsum", usage: "壁《かべ》クロスを張《は》る（memasang wallpaper）" },
  { id: 1292, category: "kenchiku_shiage", source: "vocab-exam", furi: "スタッド", jp: "スタッド", type: "vocab", id_text: "Stud baja ringan (LGS)", desc: "Profil baja C yang dipasang vertikal ke runner sebagai rangka dinding partisi.", usage: "スタッドを建《た》て込《こ》む（memasang stud）" },
  { id: 1293, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "ランナー", jp: "ランナー", type: "vocab", id_text: "Runner / rel horizontal", desc: "Profil baja berbentuk U yang dipasang di lantai dan plafon sebagai landasan dan", usage: "ランナーを固定《こてい》する（memasang runner）" },
  { id: 1294, category: "hoon", source: "vocab-supplementary", furi: "ロックウールきゅうおんばん", jp: "ロックウール吸音板", type: "vocab", id_text: "Panel akustik rockwool", desc: "Panel plafon dari rockwool yang dapat menyerap suara sekaligus memiliki sifat" },
  { id: 1295, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "ふねんざいりょう", jp: "不燃材料", type: "vocab", id_text: "Material tidak terbakar", desc: "Material yang diakui tidak dapat terbakar berdasarkan Undang-Undang Standar" },
  { id: 1296, category: "kenchiku_shiage", source: "vocab-supplementary", furi: "せっちゃくこうほう", jp: "接着工法", type: "vocab", id_text: "Metode pemasangan adhesif", desc: "Metode pemasangan tile atau board menggunakan lem organik yang dioleskan", usage: "接着工法《せっちゃくこうほう》で施工《せこう》する（memasang dengan metode adhesif）" },
  { id: 1297, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "はんまーどりる", jp: "ハンマードリル", id_text: "Bor rotary / hammer drill", desc: "例: ハンマードリルはコンクリートへの穴あけや斫り作業に使う。→ Hammer drill digunakan untuk mengebor beton dan pekerjaan bongkaran (斫り). Wajib pakai pelindung telinga saat operasi." },
  { id: 1298, category: "sekou", source: "vocab-exam", furi: "いんぱくとどらいばー", jp: "インパクトドライバー", type: "vocab", id_text: "Bor sekrup bertenaga", desc: "Alat listrik pengencang baut/sekrup.\nBerbeda dari drill biasa — ada pukulan", usage: "インパクトドライバーでビスを締《し》める（mengencangkan sekrup）" },
  { id: 1299, category: "sekou", source: "vocab-exam", furi: "ういんち", jp: "ウインチ", type: "vocab", id_text: "Winch / derek bermotor", desc: "Alat bermotor penarik material berat.\nPeriksa tali dan kapasitas sebelum", usage: "ウインチで荷物《にもつ》を引《ひ》き上《あ》げる（mengangkat material dengan winch）" },
  { id: 1300, category: "haikan", source: "vocab-supplementary", furi: "ぱいぷばいす", jp: "パイプバイス", type: "vocab", id_text: "Ragum pipa / pipe vise", desc: "Alat penjepit pipa baja sebelum proses threading; cegah pipa bergeser saat", usage: "パイプバイスで固定《こてい》する（menjepit dengan pipe vise）" },
  { id: 1301, category: "haikan", source: "vocab-supplementary", furi: "ぱいぷべんだー", jp: "パイプベンダー", type: "vocab", id_text: "Pembengkok pipa / pipe", desc: "Alat untuk menekuk pipa baja ke sudut yang ditentukan.\nPerhatikan radius", usage: "パイプベンダーで曲《ま》げる（menekuk pipa dengan pipe bender）" },
  { id: 1302, category: "sekou", source: "vocab-exam", furi: "ゆあつじゃっき", jp: "油圧ジャッキ", type: "vocab", id_text: "Dongkrak hidrolik", desc: "Alat pengangkat beban berat (hidrolik).\nLandasan wajib stabil sebelum operasi.", usage: "油圧《ゆあつ》ジャッキで持《も》ち上《あ》げる（mengangkat dengan dongkrak hidrolik）" },
  { id: 1303, category: "denki", source: "vocab-supplementary", furi: "あっちゃくこうぐ", jp: "圧着工具", type: "vocab", id_text: "Alat crimping / tang", desc: "Alat untuk menjepitkan terminal kabel guna mencegah kontak yang buruk.", usage: "圧着《あっちゃく》する（melakukan crimping）" },
  { id: 1304, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "とるくれんち", jp: "トルクレンチ", id_text: "Kunci torsi / torque wrench", desc: "例: フランジボルトの締め付けはトルクレンチで規定トルク値を守る。→ Saat mengencangkan baut flens, gunakan kunci torsi sesuai nilai torsi yang ditentukan dalam spesifikasi. Mencegah over-torque yang bisa merusak ulir atau sambungan." },
  { id: 1305, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "しゃこまんりき", jp: "シャコ万力", id_text: "Klem-C / C-clamp / ragum penjepit", desc: "例: 溶接作業中、シャコ万力で部材を固定して位置ずれを防ぐ。→ Saat pengelasan, gunakan C-clamp untuk memfix material agar tidak bergeser. Juga disebut Cクランプ. Digunakan saat menjepit papan, profil baja, atau pipa selama pengerjaan." },
  { id: 1306, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "たっぷ・だいす", jp: "タップ・ダイス", id_text: "Tap & dies / alat pembuat ulir", desc: "例: タップで金属に雌ねじを切り、ダイスで丸棒に雄ねじを切る。→ Tap digunakan untuk membuat ulir dalam (mur/雌ねじ), sedangkan dies untuk membuat ulir luar (baut/雄ねじ) pada batang logam. Keduanya adalah alat threading manual." },
  { id: 1307, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "かなきりのこ", jp: "金切りのこ", id_text: "Gergaji besi / hacksaw", desc: "例: 金切りのこは鋼管や鉄棒の手動切断に使う。刃は消耗したら交換する。→ Gergaji besi digunakan untuk memotong pipa baja, besi batang, atau profil logam secara manual. Bilah gergaji (刃) dapat diganti saat sudah aus." },
  { id: 1308, category: "haikan", source: "vocab-supplementary", furi: "ほーるそー", jp: "ホールソー", type: "vocab", id_text: "Hole saw / mata bor", desc: "Mata bor untuk membuat lubang bulat besar di dinding atau plafon untuk jalur" },
  { id: 1309, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "がすばーなー", jp: "ガスバーナー", id_text: "Pembakar gas / gas torch / burner", desc: "例: ガスバーナーは銅管のろう付けや防水材の炙り加工に使用する。→ Gas torch digunakan untuk penyolderan pipa tembaga (ろう付け/brazing) atau pemanasan material waterproofing. Pastikan ventilasi cukup dan jauh dari bahan mudah terbakar." },
  { id: 1310, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ぜつえんていこうけい", jp: "絶縁抵抗計", id_text: "Megger / alat ukur tahanan isolasi kabel", desc: "例: 絶縁抵抗計（メガー）で電線の絶縁状態を確認し、漏電がないかを検査する。→ Megger digunakan untuk mengukur resistansi isolasi kabel listrik. Memastikan tidak ada kebocoran arus (漏電) ke ground sebelum sistem dinyalakan." },
  { id: 1311, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "せっちていこうけい", jp: "接地抵抗計", id_text: "Earth tester / alat ukur tahanan grounding", desc: "例: 接地抵抗計でアース極の接地抵抗値が規定値以下かを確認する。→ Earth tester digunakan untuk mengukur nilai tahanan grounding (接地/アース) dan memastikan instalasi pembumian memenuhi standar keamanan listrik." },
  { id: 1312, category: "sekou", source: "vocab-exam", furi: "でんどうどりる", jp: "電動ドリル", type: "vocab", id_text: "Bor listrik serbaguna", desc: "Alat listrik serbaguna untuk mengebor kayu, logam, dan beton.", usage: "電動《でんどう》ドリルで穴《あな》を開《あ》ける（mengebor lubang）" },
  { id: 1313, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "えあこんぷれっさー", jp: "エアコンプレッサー", id_text: "Kompresor udara / air compressor", desc: "例: エアコンプレッサーは釘打ち機やエアブロー清掃など幅広い作業に使用される。→ Kompresor udara digunakan untuk berbagai pekerjaan: alat tembak paku (釘打ち機), pembersihan debu dengan udara bertekanan, dan pengecatan semprot." },
  { id: 1314, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "こんくりーとかったー", jp: "コンクリートカッター", id_text: "Gergaji beton / concrete cutter / floor saw", desc: "例: コンクリートカッターで床スラブに配管用の溝を切る。粉塵対策と給水が必須。→ Concrete cutter digunakan untuk memotong alur jalur pipa di lantai beton. Wajib menggunakan proteksi debu (防塵マスク) dan pendingin air saat operasi." },
  { id: 1315, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ちっぱー", jp: "チッパー", id_text: "Pahat pneumatik / chipping hammer", desc: "例: チッパーはコンクリートのはつり作業や古い仕上げ材の除去に使う。→ Chipping hammer (chipper) digunakan untuk membongkar beton (斫り/はつり) atau mengupas material finishing lama. Gunakan goggles dan pelindung telinga saat operasi." },
  { id: 1316, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "じぐそー", jp: "ジグソー", id_text: "Jigsaw / gergaji listrik serabut", desc: "例: ジグソーは曲線や複雑な形状の切断に適した電動のこぎりだ。→ Jigsaw adalah gergaji listrik yang cocok untuk memotong bentuk melengkung atau pola kompleks pada kayu, lembaran logam, atau papan gipsum di lokasi konstruksi." },
  { id: 1317, category: "sekou", source: "vocab-exam", furi: "ぼーるばん", jp: "ボール盤", type: "vocab", id_text: "Mesin bor stasioner", desc: "Mesin bor tetap untuk pengeboran presisi.\nLebih akurat dari bor listrik genggam.", usage: "ボール盤《ばん》で穴《あな》を開《あ》ける（mengebor dengan presisi）" },
  { id: 1318, category: "haikan", source: "vocab-supplementary", furi: "ぼうばくこうぐ", jp: "防爆工具", type: "vocab", id_text: "Alat anti-percikan /", desc: "Wajib digunakan saat bekerja di sekitar pipa gas atau ruang dengan gas mudah" },
  { id: 1319, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "すこや", jp: "スコヤ", id_text: "Siku presisi / try square / engineer's square", desc: "例: スコヤで部材の直角を確認してから溶接や加工を行う。→ Try square (スコヤ) digunakan untuk memeriksa sudut siku-siku (90°) pada material sebelum pengelasan atau pengerjaan lebih lanjut." },
  { id: 1320, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "ぷらいやー", jp: "プライヤー", id_text: "Tang jepit / pliers", desc: "例: プライヤーはナットや配管継手など円筒物をつかんで回す作業に使う。→ Pliers digunakan untuk mencengkeram dan memutar mur, fitting pipa, atau benda silindris lainnya." },
  { id: 1321, category: "haikan", source: "vocab-exam", furi: "しんくうぽんぷ", jp: "真空ポンプ", type: "vocab", id_text: "Pompa vakum / vacuum pump", desc: "Digunakan setelah pemasangan pipa refrigeran untuk mengosongkan udara dan", usage: "真空《しんくう》引《び》きをする（melakukan vakumisasi pipa refrigeran）" },
  { id: 1322, category: "career", source: "vocab-supplementary", type: "vocab", furi: "せこうけいかくしょ", jp: "施工計画書", id_text: "Dokumen rencana pelaksanaan konstruksi", desc: "例: 施工計画書は着工前に作成し、監理者に提出する。→ Dokumen rencana pelaksanaan dibuat sebelum mulai kerja dan diserahkan ke pengawas. Mencakup metode kerja, jadwal, keselamatan, dan pengelolaan kualitas." },
  { id: 1323, category: "career", source: "vocab-exam", furi: "ケーワイシート", jp: "KYシート", type: "vocab", id_text: "Lembar prediksi bahaya KY", desc: "Formulir tertulis identifikasi titik bahaya per sesi kerja.", usage: "KYシートを記入《きにゅう》する（mengisi lembar prediksi bahaya）" },
  { id: 1324, category: "career", source: "vocab-exam", furi: "しんきにゅうじょうしゃカード", jp: "新規入場者カード", type: "vocab", id_text: "Kartu data pekerja baru", desc: "Formulir wajib berisi data dan sertifikasi pekerja baru sebelum masuk.", usage: "新規《しんき》入場者《にゅうじょうしゃ》カードを提出《ていしゅつ》する（menyerahkan kartu pekerja baru）" },
  { id: 1325, category: "career", source: "vocab-supplementary", type: "vocab", furi: "グリーンファイル", jp: "グリーンファイル", id_text: "Green file — kumpulan dokumen keselamatan", desc: "例: グリーンファイルには、安全衛生計画書・KY記録・作業員名簿などが綴られる。→ Green file memuat rencana K3, catatan KY, daftar tenaga kerja, dll. Disimpan di lokasi dan diperiksa oleh pengawas proyek." },
  { id: 1327, category: "career", source: "vocab-supplementary", type: "vocab", furi: "バーチャート", jp: "バーチャート", id_text: "Jadwal balok (Gantt chart konstruksi)", desc: "例: バーチャートは見やすいが、作業の関連性が分かりにくい。→ Jadwal balok mudah dibaca tapi tidak menunjukkan ketergantungan antar pekerjaan. Cocok untuk proyek sederhana atau laporan kemajuan ke klien." },
  { id: 1328, category: "career", source: "vocab-supplementary", type: "vocab", furi: "ネットワークこうていひょう", jp: "ネットワーク工程表", id_text: "Jadwal jaringan / CPM schedule", desc: "例: ネットワーク工程表でクリティカルパスを特定し、遅延リスクを管理した。→ Dengan jadwal jaringan, jalur kritis diidentifikasi untuk mengelola risiko keterlambatan. Menunjukkan urutan dan ketergantungan antar pekerjaan." },
  { id: 1329, category: "career", source: "vocab-supplementary", type: "vocab", furi: "できだか", jp: "出来高", id_text: "Nilai pekerjaan yang telah selesai (progres)", desc: "例: 今月の出来高は契約金額の40%に達した。→ Progres bulan ini mencapai 40% dari nilai kontrak. Digunakan untuk penagihan bertahap (partial billing) dan laporan kemajuan proyek." },
  { id: 1330, category: "career", source: "vocab-supplementary", type: "vocab", furi: "ぶがかり", jp: "歩掛り", id_text: "Koefisien produktivitas tenaga kerja", desc: "例: 配管工事の歩掛りは、1mあたり何人工かかるかを示す。→ Koefisien kerja pipa menunjukkan berapa orang-hari yang dibutuhkan per meter. Digunakan untuk estimasi biaya tenaga kerja dalam RAB." },
  { id: 1331, category: "career", source: "vocab-supplementary", type: "vocab", furi: "ちょくせつかせつ", jp: "直接仮設", id_text: "Pekerjaan sementara langsung (per lokasi)", desc: "例: 直接仮設には、各工事専用の足場・型枠支保工などが含まれる。→ Pekerjaan sementara langsung mencakup perancah dan bekisting yang khusus untuk satu area pekerjaan tertentu. Berbeda dari 共通仮設." },
  { id: 1332, category: "career", source: "vocab-supplementary", type: "vocab", furi: "きょうつうかせつ", jp: "共通仮設", id_text: "Pekerjaan sementara bersama (seluruh proyek)", desc: "例: 共通仮設には、現場事務所・トイレ・電力引込などが含まれる。→ Pekerjaan sementara bersama mencakup kantor lapangan, toilet, dan sambungan listrik yang dipakai semua pihak di proyek." },
  { id: 1333, category: "career", source: "vocab-supplementary", type: "vocab", furi: "げんかかんり", jp: "原価管理", id_text: "Manajemen biaya / pengendalian harga pokok", desc: "例: 原価管理では、実際原価と計画原価を比較して差異を分析する。→ Dalam manajemen biaya, biaya aktual dibandingkan dengan biaya rencana untuk menganalisis selisih. Termasuk dalam 4 pilar施工管理 (Q, C, D, S)." },
  { id: 1334, category: "career", source: "vocab-exam", furi: "せっけいとしょ", jp: "設計図書", type: "vocab", id_text: "Dokumen desain proyek", desc: "Paket dokumen proyek: gambar, spesifikasi, dan penjelasan lapangan." },
  { id: 1335, category: "career", source: "vocab-supplementary", type: "vocab", furi: "しゅんこうず", jp: "竣工図", id_text: "Gambar as-built (setelah selesai dibangun)", desc: "例: 竣工図は、実際に施工した内容を反映した最終図面で、引渡し時に提出する。→ Gambar as-built mencerminkan kondisi yang benar-benar dibangun, diserahkan saat serah terima ke klien. Berbeda dari gambar desain awal." },
  { id: 1336, category: "career", source: "vocab-supplementary", type: "vocab", furi: "せこうず", jp: "施工図", id_text: "Gambar kerja lapangan (shop drawing)", desc: "例: 施工図は設計図書をもとに現場で作業できるよう詳細化した図面である。→ Gambar kerja adalah gambar detail yang dibuat dari dokumen desain agar bisa langsung digunakan di lapangan. Dibuat oleh kontraktor, disetujui pengawas." },
  { id: 1337, category: "career", source: "vocab-supplementary", type: "vocab", furi: "うちあわせきろく", jp: "打合せ記録", id_text: "Notulen / catatan rapat koordinasi", desc: "例: 打合せ記録には、日時・参加者・決定事項・担当者を明記する。→ Notulen rapat mencantumkan tanggal, peserta, keputusan, dan penanggung jawab. Dokumen penting sebagai bukti kesepakatan di lapangan." },
  { id: 1338, category: "career", source: "vocab-supplementary", type: "vocab", furi: "こうじにっぽう", jp: "工事日報", id_text: "Laporan harian pekerjaan konstruksi", desc: "例: 工事日報には、当日の作業内容・人員数・天気・問題点を記録する。→ Laporan harian mencatat jenis pekerjaan, jumlah tenaga kerja, cuaca, dan kendala hari itu. Diisi oleh pengawas lapangan setiap hari." },
  { id: 1339, category: "career", source: "vocab-supplementary", type: "vocab", furi: "ざいりょうはんにゅう", jp: "材料搬入", id_text: "Pengiriman / penerimaan material ke lokasi", desc: "例: 材料搬入時は、納品書と照合して数量・品番を確認する。→ Saat material tiba, jumlah dan nomor produk dicocokkan dengan surat jalan. Proses ini mendahului 検収 (penerimaan resmi setelah inspeksi)." },
  { id: 1340, category: "career", source: "vocab-general", type: "vocab", furi: "けんしゅう", jp: "検収", id_text: "Inspeksi & penerimaan material resmi", desc: "例: 検収では、材料の品質・数量・規格が仕様書と一致するか確認する。→ Dalam inspeksi penerimaan, kualitas, jumlah, dan spesifikasi material dikonfirmasi sesuai dokumen. Setelah 検収 dinyatakan lulus, material sah digunakan." },
  { id: 1341, category: "career", source: "vocab-general", type: "vocab", furi: "ぜせい", jp: "是正", id_text: "Tindakan koreksi / perbaikan ketidaksesuaian", desc: "例: 検査で不適合が見つかり、是正処置を施工者に指示した。→ Ketidaksesuaian ditemukan saat inspeksi, dan tindakan koreksi diperintahkan ke kontraktor. Dalam sistem ISO 9001, 是正処置は根本原因の除去を含む." },
  { id: 1342, category: "career", source: "vocab-supplementary", type: "vocab", furi: "ひきわたし", jp: "引渡し", id_text: "Serah terima bangunan / fasilitas ke klien", desc: "例: 引渡し前に竣工検査を行い、合格後に鍵と竣工図書を施主に渡す。→ Sebelum serah terima, inspeksi akhir dilakukan; lulus → kunci dan dokumen diserahkan ke pemilik. Menandai berakhirnya tanggung jawab kontraktor." },
  { id: 1343, category: "career", source: "vocab-exam", furi: "せこうたいせいだいちょう", jp: "施工体制台帳", type: "vocab", id_text: "Buku struktur kontraktor", desc: "Catatan semua kontraktor (utama, sub, spesialis) dalam satu proyek." },
  { id: 1344, category: "career", source: "vocab-supplementary", type: "vocab", furi: "そうごうせこうけいかくしょ", jp: "総合施工計画書", id_text: "Rencana pelaksanaan konstruksi menyeluruh", desc: "例: 総合施工計画書は工事全体を俯瞰した計画書で、着工前に作成される。→ Dokumen ini merangkum rencana keseluruhan proyek dan dibuat sebelum pekerjaan dimulai. Menjadi acuan bagi semua 施工計画書 per bidang pekerjaan." },
  { id: 1345, category: "career", source: "vocab-supplementary", type: "vocab", furi: "ひんしつかんりけいかくしょ", jp: "品質管理計画書", id_text: "Dokumen rencana manajemen kualitas", desc: "例: 品質管理計画書には、検査項目・頻度・担当者・合否基準を定める。→ Dokumen ini menetapkan item inspeksi, frekuensi, penanggung jawab, dan kriteria lulus/gagal. Bagian dari sistem ISO 9001 yang diterapkan di proyek konstruksi." },
  { id: 1346, category: "hourei", source: "vocab-teori", furi: "きょか", jp: "許可", type: "hukum", id_text: "Izin usaha konstruksi", desc: "Wajib mendapat izin dari gubernur/menteri sebelum menjalankan usaha konstruksi.", quote: undefined },
  { id: 1347, category: "hourei", source: "vocab-teori", furi: "うけおいけいやく", jp: "請負契約", type: "hukum", id_text: "Kontrak borongan", desc: "Kontrak antara pemilik proyek dan kontraktor utama untuk pekerjaan konstruksi.", quote: undefined },
  { id: 1348, category: "hourei", source: "vocab-teori", furi: "もとうけ", jp: "元請け", type: "hukum", id_text: "Kontraktor utama", desc: "Pihak yang menerima proyek langsung dari pemilik dan mengelola semua sub-kontraktor.", quote: undefined },
  { id: 1349, category: "hourei", source: "vocab-teori", furi: "したうけ", jp: "下請け", type: "hukum", id_text: "Sub-kontraktor", desc: "Pihak yang menerima pekerjaan dari kontraktor utama.\nBisa berlapis: 二次《にじ》・三次《さんじ》下請《したう》けけ《したうけ》.", quote: undefined },
  { id: 1350, category: "hourei", source: "vocab-teori", furi: "ろうどうきじゅんかんとくしょ", jp: "労働基準監督署", type: "hukum", id_text: "Lembaga pengawas kerja", desc: "Instansi pengawas kepatuhan UU Ketenagakerjaan.\nKecelakaan kerja wajib dilaporkan segera.", quote: undefined },
  { id: 1351, category: "hourei", source: "vocab-teori", furi: "ゆうきゅうきゅうか", jp: "有給休暇", type: "hukum", id_text: "Cuti berbayar", desc: "10 hari cuti setelah 6 bulan kerja, kehadiran ≥80%.\nDiatur 労働《ろうどう》基準《きじゅん》法《ほう》.", quote: undefined },
  { id: 1352, category: "hourei", source: "vocab-teori", furi: "わりましちんぎん", jp: "割増賃金", type: "hukum", id_text: "Upah lembur premi", desc: "Upah lembur minimal 1,25× gaji normal sesuai UU.\nLembur >60 jam/bulan = 1,5×.", quote: undefined },
  { id: 1353, category: "hourei", source: "vocab-teori", furi: "ばっそく", jp: "罰則", type: "hukum", id_text: "Sanksi hukum / pidana", desc: "Sanksi atas pelanggaran UU Konstruksi berupa pencabutan izin atau denda.", quote: undefined },
  { id: 1354, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "あんぜんかんりしゃ", jp: "安全管理者", id_text: "Safety manager / manajer keselamatan kerja", desc: "例: 常時50人以上の事業場には安全管理者の選任が義務付けられている。→ Wajib ada safety manager di tempat kerja dengan ≥50 pekerja tetap. Berbeda dari 衛生管理者 yang fokus pada kesehatan." },
  { id: 1356, category: "anzen", source: "vocab-teori", furi: "さんだいさいがい", jp: "三大災害", type: "vocab", id_text: "3 besar kecelakaan kerja", desc: "Tiga kecelakaan konstruksi tersering: jatuh, mesin berat, dan runtuh." },
  { id: 1357, category: "anzen", source: "vocab-teori", furi: "あんぜんたい", jp: "安全帯", type: "vocab", id_text: "Sabuk/harness keselamatan", desc: "Alat pelindung jatuh di ketinggian.\nSejak 2022, full-harness adalah standar", usage: "安全《あんぜん》帯《たい》を装着《そうちゃく》する（memakai harness keselamatan）" },
  { id: 1358, category: "anzen", source: "vocab-teori", furi: "ふるはーねすがた", jp: "フルハーネス型", type: "vocab", id_text: "Full-harness ketinggian", desc: "Harness tipe seluruh tubuh.\nWajib di ketinggian ≥5 m — lebih aman dari sabuk", usage: "フルハーネス型《がた》を着用《ちゃくよう》する（memakai full-body harness）" },
  { id: 1359, category: "anzen", source: "vocab-teori", furi: "たちいりきんし", jp: "立入禁止", type: "vocab", id_text: "Area dilarang masuk", desc: "Zona terlarang ditandai tali dan papan — wajib di area ayunan alat berat." },
  { id: 1360, category: "anzen", source: "vocab-teori", furi: "ほごぐ", jp: "保護具", type: "vocab", id_text: "APD / alat pelindung diri", desc: "Perlengkapan pelindung diri.\nDasar di site: helm, sepatu safety, dan harness.", usage: "保護《ほご》具《ぐ》を着用《ちゃくよう》する（memakai APD）" },
  { id: 1361, category: "anzen", source: "vocab-teori", furi: "かんでん", jp: "感電", type: "vocab", id_text: "Sengatan listrik", desc: "Selalu matikan sumber listrik sebelum bekerja.\nBisa berakibat fatal." },
  { id: 1364, category: "sekou", source: "vocab-teori", furi: "せこうけいかく", jp: "施工計画", type: "vocab", id_text: "Rencana pelaksanaan", desc: "Rencana kerja sebelum konstruksi: jadwal, kualitas, dan keselamatan.", usage: "施工《せこう》計画《けいかく》を立《た》てる（menyusun rencana pelaksanaan）" },
  { id: 1365, category: "sekou", source: "vocab-supplementary", type: "vocab", furi: "こうていひょう", jp: "工程表", id_text: "Bagan jadwal konstruksi (Gantt chart / network)", desc: "例: 工程表で各作業の開始・終了予定日と担当者を管理する。→ Jadwal menampilkan tanggal mulai/selesai setiap pekerjaan. バーチャート = mudah dibaca; ネットワーク工程表 = menampilkan ketergantungan antar pekerjaan." },
  { id: 1368, category: "hourei", source: "vocab-teori", furi: "はっちゅうしゃ", jp: "発注者", type: "hukum", id_text: "Pemilik / pemberi proyek", desc: "Pihak yang memesan proyek, menentukan isi/durasi/anggaran, dan menandatangani kontrak borongan.", quote: undefined },
  { id: 1369, category: "hourei", source: "vocab-supplementary", type: "vocab", furi: "せんもんぎょうしゃ", jp: "専門業者", id_text: "Kontraktor spesialis / specialty contractor", desc: "例: 電気・空調・配管などは各分野の専門業者が施工する。→ Listrik, AC, dan perpipaan dikerjakan oleh kontraktor spesialis masing-masing bidang. 元請けが全体調整し、各専門業者が実施工を担う." },
  { id: 1370, category: "haikan", source: "vocab-teori", furi: "れいばい", jp: "冷媒", type: "vocab", id_text: "Refrigeran / zat", desc: "Zat pendingin dalam pipa AC (HFC dll).\nSambungan pipa refrigeran wajib diuji" },
  { id: 1371, category: "haikan", source: "vocab-teori", furi: "こうばい", jp: "勾配", type: "vocab", id_text: "Kemiringan pipa drainase", desc: "Kemiringan pada pipa drainase agar air mengalir secara gravitasi." },
  { id: 1372, category: "haikan", source: "vocab-teori", furi: "すいあつしけん", jp: "水圧試験", type: "vocab", id_text: "Uji tekanan hidraulik", desc: "Uji kebocoran pipa setelah pemasangan selesai. Tekanan uji sesuai nilai yang", usage: "水圧《すいあつ》試験《しけん》を実施《じっし》する（melakukan uji tekanan hidraulik）" },
  { id: 1373, category: "haikan", source: "vocab-supplementary", furi: "もれしけん", jp: "漏れ試験", type: "vocab", id_text: "Uji kebocoran", desc: "Wajib dilakukan setelah pengelasan atau penyambungan pipa sebelum sistem" },
  { id: 1374, category: "haikan", source: "vocab-teori", furi: "さどる", jp: "サドル", type: "vocab", id_text: "Saddle / braket penopang", desc: "Braket untuk menempelkan pipa ke dinding, plafon, atau lantai.\nJarak saddle" },
  { id: 1375, category: "haikan", source: "vocab-teori", furi: "つぎて", jp: "継手", type: "vocab", id_text: "Fitting / komponen", desc: "Komponen penghubung antar pipa. Jenis: elbow (belok), tee (T), socket (lurus)." },
  { id: 1376, category: "haikan", source: "vocab-teori", furi: "ふらんじ", jp: "フランジ", type: "vocab", id_text: "Flensa / sambungan baut", desc: "Sambungan pipa menggunakan baut; mudah dibuka untuk perawatan dibanding las", usage: "フランジ接合《せつごう》する（menyambung dengan flensa）" },
  { id: 1377, category: "haikan", source: "vocab-teori", furi: "ばるぶ", jp: "バルブ", type: "vocab", id_text: "Katup / valve", desc: "Mengatur buka/tutup aliran. Jenis: gate (全開《ぜんかい》/全閉《ぜんへい》), ball (cepat)," },
  { id: 1378, category: "denki", source: "vocab-teori", furi: "はいせん", jp: "配線", type: "vocab", id_text: "Pengkabelan / wiring", desc: "Instalasi kabel listrik sesuai gambar: ukuran, jenis, dan rute harus tepat." },
  { id: 1379, category: "denki", source: "vocab-teori", furi: "ぶんき", jp: "分岐", type: "vocab", id_text: "Percabangan / branch", desc: "Pembagian dari jalur utama ke jalur-jalur cabang. Berlaku untuk listrik maupun" },
  { id: 1380, category: "denki", source: "vocab-teori", furi: "でんねつせん", jp: "電熱線", type: "vocab", id_text: "Kabel pemanas anti-beku", desc: "Kawat pemanas yang dililitkan pada pipa luar ruangan di daerah dingin untuk" },
  { id: 1381, category: "gaiyou", source: "vocab-jac", furi: "おはようございます", jp: "おはようございます", type: "vocab", id_text: "Selamat pagi (formal)", desc: "Sapaan pagi formal.\nDi site konstruksi, sering dipakai sepanjang hari." },
  { id: 1382, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "よろしくおねがいします", jp: "よろしくお願いします", id_text: "Mohon bimbingannya / salam kenal (serba guna)", desc: "例: 初日の挨拶「よろしくお願いします」／作業依頼の最後にも使う。→ Dipakai saat: pertama kali bertemu, menitipkan tugas ke orang lain, memohon bantuan. Frasa yang paling sering dibutuhkan di lapangan." },
  { id: 1383, category: "gaiyou", source: "vocab-jac", furi: "ありがとうございます", jp: "ありがとうございます", type: "vocab", id_text: "Terima kasih (formal)", desc: "Ucapan terima kasih formal setelah dibantu atau menerima sesuatu." },
  { id: 1384, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "すみません", jp: "すみません", id_text: "Permisi / maaf / excuse me (serbaguna)", desc: "例: 通路をふさいでいるとき「すみません」／何か頼むときにも使う。→ Dipakai untuk: meminta izin lewat, minta tolong, meminta perhatian seseorang, atau minta maaf ringan. Frasa paling serbaguna di tempat kerja Jepang." },
  { id: 1385, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "わかりました", jp: "わかりました", id_text: "Sudah mengerti / paham (merespons instruksi)", desc: "例: 監督から指示を受けたら「わかりました」と返事する。→ Respons standar saat menerima instruksi dari atasan. Lebih formal dari 分かった (wakata). Wajib biasakan ini agar tidak dianggap tidak mendengarkan." },
  { id: 1386, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "わかりません", jp: "わかりません", id_text: "Tidak mengerti / tidak tahu", desc: "例: 指示が聞き取れなかったら「わかりません。もう一度お願いします」と言う。→ Jika tidak mengerti, selalu bilang dengan jelas — jangan pura-pura mengerti! Tambahkan もう一度お願いします untuk minta diulang." },
  { id: 1387, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "もういちどいってください", jp: "もう一度言ってください", id_text: "Tolong ulangi sekali lagi", desc: "例: 聞き取れなかったとき「すみません、もう一度言ってください」。→ Kalimat wajib untuk meminta pengulangan. Tidak perlu malu menggunakannya — lebih baik bertanya daripada melakukan pekerjaan yang salah." },
  { id: 1388, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "てつだってください", jp: "手伝ってください", id_text: "Tolong bantu saya", desc: "例: 重い材料を運ぶとき「手伝ってください」と頼む。→ Minta bantuan saat mengangkat beban berat, kesulitan teknis, dsb. Versi lebih sopan: お手伝いいただけますか？" },
  { id: 1389, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "ちょっとまってください", jp: "ちょっと待ってください", id_text: "Tolong tunggu sebentar", desc: "例: 準備が終わっていないとき「ちょっと待ってください」と言う。→ Minta waktu sebentar sebelum mulai atau menjawab. Sopan dan alami di lapangan. ちょっと = sedikit/sebentar." },
  { id: 1390, category: "gaiyou", source: "vocab-jac", furi: "おさきにしつれいします", jp: "お先に失礼します", type: "vocab", id_text: "Pamit pulang lebih dulu", desc: "Ucapan saat pulang duluan.\nWajib — tidak bilang ini dianggap tidak sopan." },
  { id: 1391, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "おつかれさまでした", jp: "お疲れ様でした", id_text: "Terima kasih kerja kerasnya (akhir hari / selesai)", desc: "例: 一日の作業が終わったとき「お疲れ様でした」と言い合う。→ Ucapkan di akhir shift kepada semua orang. Berbeda dari お疲れ様です (sedang berlangsung) vs です (formal ongoing). Respon yang sama: お疲れ様でした." },
  { id: 1392, category: "gaiyou", source: "vocab-jac", furi: "りょうかいしました", jp: "了解しました", type: "vocab", id_text: "Siap bertindak / roger", desc: "Konfirmasi aktif bahwa instruksi dipahami dan siap dilaksanakan." },
  { id: 1393, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "おわりました", jp: "終わりました", id_text: "Sudah selesai (laporan penyelesaian tugas)", desc: "例: 作業が完了したら監督に「○○の作業が終わりました」と報告する。→ Laporan setelah menyelesaikan tugas. Selalu laporkan ke pengawas saat pekerjaan selesai — jangan diam saja. Bisa ditambahkan: 確認をお願いします (mohon diperiksa)." },
  { id: 1394, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "きをつけて", jp: "気をつけて", id_text: "Hati-hati! / Be careful! (kepada orang lain)", desc: "例: 危険な場所を通る仲間に「気をつけて」と声をかける。→ Ucapkan kepada rekan yang sedang melewati area berbahaya atau pulang kerja. Versi lebih kuat: 気をつけてください (formal) atau 危ない！ (darurat)." },
  { id: 1395, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "おねがいします", jp: "お願いします", id_text: "Mohon / tolong (saat meminta sesuatu)", desc: "例: 資材を運んでほしいとき「○○をお願いします」と頼む。→ Tambahkan setelah permintaan apapun: 確認をお願いします (tolong cek), 手伝いをお願いします (tolong bantu), dll. Lebih sopan dari ください saja." },
  { id: 1396, category: "gaiyou", source: "vocab-jac", furi: "かくにんします", jp: "確認します", type: "vocab", id_text: "Akan saya cek dahulu", desc: "Ucapan saat butuh cek dulu sebelum menjawab.\nJangan bilang OK bila belum yakin." },
  { id: 1397, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "いってきます／いってらっしゃい", jp: "行ってきます／行ってらっしゃい", id_text: "Hati-hati di jalan (pasangan sapaan saat pergi)", desc: "例: 現場に向かう前「行ってきます」→ 残る人「行ってらっしゃい」。→ Pasangan sapaan saat seseorang berangkat meninggalkan tempat. Juga dipakai antar rekan kerja di site besar." },
  { id: 1398, category: "gaiyou", source: "vocab-supplementary", type: "vocab", furi: "おせわになっております", jp: "お世話になっております", id_text: "Terima kasih atas bimbingan selama ini (formal)", desc: "例: 電話や会議の冒頭「お世話になっております、○○の田中です」。→ Kalimat pembuka formal dalam telepon atau rapat. Setara dengan 'thank you for your continued support'. Wajib di lingkungan kerja profesional Jepang." },
  { id: 1399, category: "career", source: "vocab-jac", furi: "ほうこく", jp: "報告", type: "vocab", id_text: "Laporan kepada atasan", desc: "Melaporkan hasil kerja atau masalah kepada atasan secara langsung.", usage: "報告《ほうこく》する（melaporkan ke atasan）" },
  { id: 1400, category: "career", source: "vocab-jac", furi: "れんらく", jp: "連絡", type: "vocab", id_text: "Pemberitahuan antar tim", desc: "Berbagi informasi antar anggota tim agar koordinasi berjalan lancar.", usage: "連絡《れんらく》する（memberitahu / menghubungi）" },
  { id: 1401, category: "career", source: "vocab-jac", furi: "そうだん", jp: "相談", type: "vocab", id_text: "Konsultasi dengan atasan", desc: "Tanyakan kepada senior jika tidak yakin — jangan coba-coba sendiri.", usage: "相談《そうだん》する（berkonsultasi）" },
  { id: 1402, category: "career", source: "vocab-jac", furi: "ほうれんそう", jp: "ほう・れん・そう", type: "vocab", id_text: "3 pilar komunikasi kerja", desc: "Tiga pilar komunikasi kerja di Jepang: Lapor, Hubungi, Konsultasi." },
  { id: 1403, category: "career", source: "vocab-jac", furi: "しじ", jp: "指示", type: "vocab", id_text: "Instruksi kerja", desc: "Arahan dari atasan.\nCatat, respons dengan jelas, jangan bertindak tanpa", usage: "指示《しじ》に従《したが》う（mengikuti instruksi）" },
  { id: 1404, category: "career", source: "vocab-general", type: "vocab", furi: "けいご", jp: "敬語", id_text: "Bahasa hormat Jepang (kepada atasan/klien)", desc: "例: 上司や発注者には敬語を使う。「食べる」→「いただく」、「言う」→「おっしゃる」。→ Bahasa hormat digunakan kepada atasan, senior, dan klien. Keigo dasar: ～ます/～ます form = sudah cukup di lapangan." },
  { id: 1405, category: "career", source: "vocab-supplementary", type: "vocab", furi: "みだしなみ", jp: "身だしなみ", id_text: "Penampilan / kerapian diri di tempat kerja", desc: "例: 現場では清潔な作業着・正しくかぶったヘルメット・安全靴が身だしなみの基本。→ Penampilan di site: seragam bersih, helm benar, sepatu safety. 身だしなみが良い = kesan profesional, kepercayaan atasan meningkat." },
  { id: 1406, category: "career", source: "vocab-general", type: "vocab", furi: "ちこく", jp: "遅刻", id_text: "Terlambat / keterlambatan masuk kerja", desc: "例: 遅刻しそうなときは、必ず事前に上司に連絡する。無断遅刻は厳禁。→ Jika akan terlambat, WAJIB hubungi atasan lebih dulu. Terlambat tanpa kabar (無断遅刻) = pelanggaran serius. 朝礼の時間に間に合うよう余裕を持って出勤する。" },
  { id: 1407, category: "career", source: "vocab-general", type: "vocab", furi: "けっきん", jp: "欠勤", id_text: "Tidak masuk kerja / absen", desc: "例: 体調不良で欠勤する場合は、始業時間前に会社へ電話連絡する。→ Kalau sakit dan tidak bisa masuk, telepon perusahaan SEBELUM jam kerja dimulai. 無断欠勤 = 最悪の場合、解雇の原因になる。欠勤の際は診断書が必要な場合もある。" },
  { id: 1408, category: "career", source: "vocab-jac", furi: "とどけで", jp: "届け出", type: "vocab", id_text: "Pelaporan resmi ke atasan", desc: "Pemberitahuan resmi wajib untuk absen, terlambat, atau pulang awal.", usage: "届《とど》け出《で》を提出《ていしゅつ》する（menyerahkan pemberitahuan resmi）" },
  { id: 1409, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "たいちょうかんり", jp: "体調管理", id_text: "Manajemen kondisi fisik / menjaga kesehatan diri", desc: "例: プロとして毎日の体調管理は自分の責任だ。睡眠・食事・水分補給の3つが基本。→ Sebagai profesional, menjaga kondisi tubuh adalah tanggung jawab pribadi. 体調不良で作業すると事故・ミスの原因になる。JAC テキスト必出トピック。" },
  { id: 1410, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "たいちょうふりょう", jp: "体調不良", id_text: "Kondisi badan tidak fit / merasa tidak enak badan", desc: "例: 体調不良を感じたら無理せず、すぐに上司に「体調が悪いです」と報告する。→ Kalau tidak enak badan, jangan dipaksakan — langsung lapor ke atasan. 高所作業・機械操作中の体調不良は重大事故の原因になる。" },
  { id: 1411, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "すいぶんほきゅう", jp: "水分補給", id_text: "Minum air / rehidrasi (cegah heat stroke)", desc: "例: 夏の現場では、1時間ごとに水分補給して熱中症を予防する。→ Di musim panas, minum air setiap jam untuk cegah heat stroke. のどが渇く前に飲む = minum sebelum merasa haus. スポーツドリンクで電解質も補充する。" },
  { id: 1412, category: "career", source: "vocab-jac", furi: "きゅうけい", jp: "休憩", type: "vocab", id_text: "Istirahat kerja (break)", desc: ">6 jam kerja = istirahat 45 menit; >8 jam = 60 menit.", usage: "休憩《きゅうけい》を取《と》る（mengambil waktu istirahat）" },
  { id: 1413, category: "career", source: "vocab-jac", furi: "ざんぎょう", jp: "残業", type: "vocab", id_text: "Kerja lembur", desc: "Kerja di luar jam normal, dibayar upah premi min 1,25×.\nBatas: 45 jam/bulan.", usage: "残業《ざんぎょう》する（bekerja lembur）" },
  { id: 1414, category: "career", source: "vocab-supplementary", type: "vocab", furi: "じかんげんしゅ", jp: "時間厳守", id_text: "Tepat waktu / kepatuhan terhadap jadwal", desc: "例: 朝礼・作業開始・材料搬入など、すべての時間を厳守することが信頼の基本。→ Semua jadwal — apel, mulai kerja, pengiriman material — harus tepat waktu. 「5分前行動」= siap 5 menit sebelum waktu yang ditetapkan. Kebiasaan di Jepang." },
  { id: 1415, category: "career", source: "vocab-supplementary", type: "vocab", furi: "きゅうよめいさい", jp: "給与明細", id_text: "Slip gaji / rincian pembayaran upah bulanan", desc: "例: 毎月の給与明細を確認し、残業代・各種控除が正しいか確認する。→ Cek slip gaji setiap bulan: pastikan upah lembur dan potongan sudah benar. 不明な点は会社の担当者に相談する権利がある。給与明細の交付は法律上の義務。" },
  { id: 1416, category: "hourei", source: "vocab-teori", furi: "とくていぎのう", jp: "特定技能", type: "hukum", id_text: "SSW / status kerja Jepang", desc: "Status tinggal 2019 untuk 14 bidang; SSW 1号《ごう》 maks 5 tahun, SSW 2号《ごう》 renewable.", quote: undefined },
  { id: 1417, category: "hourei", source: "vocab-teori", furi: "ざいりゅうかーど", jp: "在留カード", type: "hukum", id_text: "Kartu izin tinggal", desc: "Wajib dibawa dan ditunjukkan bila diminta polisi/imigrasi.\nPerubahan alamat: lapor dalam 14 hari.", quote: undefined },
  { id: 1418, category: "hourei", source: "vocab-teori", furi: "ざいりゅうしかく", jp: "在留資格", type: "hukum", id_text: "Jenis status izin tinggal", desc: "Menentukan jenis pekerjaan yang boleh dilakukan.\nBekerja di luar kategori = pelanggaran hukum.", quote: undefined },
  { id: 1419, category: "hourei", source: "vocab-teori", furi: "ざいりゅうきかん", jp: "在留期間", type: "hukum", id_text: "Masa berlaku izin tinggal", desc: "SSW1 maks 5 tahun; wajib perpanjang sebelum kedaluwarsa.\nMelewati batas = overstay, bisa diusir.", quote: undefined },
  { id: 1420, category: "hourei", source: "vocab-general", type: "vocab", furi: "しゅうろう", jp: "就労", id_text: "Bekerja / kegiatan kerja berdasarkan izin tinggal", desc: "例: 在留資格の範囲外での就労は「不法就労」として処罰される。雇用主も罰則の対象。→ Kerja di luar izin tinggal = kerja ilegal, bisa dipenjara/dideportasi. Majikan juga kena sanksi. 特定技能では指定分野のみ就労可。" },
  { id: 1421, category: "hourei", source: "vocab-teori", furi: "こうしん", jp: "更新", type: "hukum", id_text: "Perpanjangan izin tinggal", desc: "Dapat diajukan mulai 3 bulan sebelum kedaluwarsa.\nBerlaku juga untuk perpanjangan kontrak dan SIM.", quote: undefined },
  { id: 1422, category: "hourei", source: "vocab-teori", furi: "しゃかいほけん", jp: "社会保険", type: "hukum", id_text: "Asuransi sosial wajib", desc: "Istilah umum untuk semua asuransi wajib.\nBiaya ditanggung bersama antara perusahaan dan karyawan.", quote: undefined },
  { id: 1423, category: "hourei", source: "vocab-teori", furi: "けんこうほけん", jp: "健康保険", type: "hukum", id_text: "Asuransi kesehatan wajib", desc: "Biaya medis jadi 30% tanggungan sendiri — 70% ditanggung.\nKartu wajib dibawa ke rumah sakit.", quote: undefined },
  { id: 1424, category: "hourei", source: "vocab-supplementary", type: "vocab", furi: "こうせいねんきん", jp: "厚生年金", id_text: "Pensiun perusahaan / employees' pension insurance", desc: "例: 厚生年金保険料は会社と従業員で折半し、将来の年金受給権が積み上がる。→ Premi pensiun ditanggung bersama (50%:50%). Setelah pensiun, berhak menerima uang pensiun. 外国人は帰国時に「脱退一時金」を受け取れる場合あり。" },
  { id: 1425, category: "hourei", source: "vocab-teori", furi: "こようほけん", jp: "雇用保険", type: "hukum", id_text: "Asuransi ketenagakerjaan", desc: "Tunjangan pengangguran jika kehilangan pekerjaan.\nBiaya ditanggung bersama antara perusahaan dan", quote: undefined },
  { id: 1426, category: "hourei", source: "vocab-supplementary", type: "vocab", furi: "ほけんしょう", jp: "保険証", id_text: "Kartu asuransi kesehatan / health insurance card", desc: "例: 病院に行くときは保険証を持参する。提示することで3割負担になる。紛失したらすぐ会社に連絡。→ Bawa kartu asuransi setiap kali ke dokter. 忘れた場合は一旦全額負担になるが後で差額が戻る場合あり。" },
  { id: 1427, category: "anzen", source: "vocab-teori", furi: "へるめっと", jp: "ヘルメット", type: "vocab", id_text: "Helm keselamatan", desc: "Helm wajib di seluruh area site konstruksi.\nTali dagu harus dikencangkan.", usage: "ヘルメットを着用《ちゃくよう》する（memakai helm keselamatan）" },
  { id: 1428, category: "anzen", source: "vocab-teori", furi: "あんぜんぐつ", jp: "安全靴", type: "vocab", id_text: "Sepatu safety", desc: "Sepatu berujung baja pelindung kaki.\nWajib di site — sepatu biasa tidak boleh.", usage: "安全《あんぜん》靴《くつ》を履《は》く（memakai sepatu safety）" },
  { id: 1429, category: "anzen", source: "vocab-supplementary", type: "vocab", furi: "ぼうじんますく", jp: "防じんマスク", id_text: "Masker anti-debu / dust respirator", desc: "例: コンクリート切断・はつり作業では防じんマスク（DS2以上）を着用する。→ Saat memotong beton/keramik, wajib pakai masker anti-debu. 通常のマスク（布・サージカル）では粉じん・シリカを防げない。塵肺（じんぱい）予防のために必須。" },
  { id: 1430, category: "anzen", source: "vocab-general", type: "vocab", furi: "みみせん", jp: "耳栓", id_text: "Penyumbat telinga / earplugs", desc: "例: 85dB以上の騒音環境（グラインダー・チッパー使用時）では耳栓または耳覆いを着用する義務がある。→ Lingkungan >85 dB wajib pakai pelindung telinga. Paparan bising berkepanjangan → 騒音性難聴 (tuli akibat kebisingan) yang tidak bisa sembuh." },
  { id: 1431, category: "anzen", source: "vocab-teori", furi: "ほごめがね", jp: "保護めがね", type: "vocab", id_text: "Kacamata pelindung", desc: "Pelindung mata dari percikan.\nWajib saat menggerinda — pengguna lensa kontak", usage: "保護《ほご》めがねを着用《ちゃくよう》する（memakai kacamata pelindung）" },
  { id: 1433, category: "career", source: "vocab-teori", furi: "けんせつきゃりああっぷしすてむ", jp: "CCUS（建設キャリアアップシステム）", type: "vocab", id_text: "CCUS kartu rekam karier", desc: "Kartu IC pencatat riwayat kerja dan level keahlian.\nSSW dianjurkan mendaftar.", usage: "CCUSカードを打刻《だこく》する（tap kartu CCUS setiap hari）" },
  { id: 1434, category: "career", source: "vocab-teori", furi: "ぎのうれべる", jp: "技能レベル", type: "vocab", id_text: "Level keahlian CCUS (1–4)", desc: "Penilaian 4 level: 1=magang, 4=mandor.\nLevel tinggi = upah dan peluang makin", usage: "技能《ぎのう》レベルを上《あ》げる（meningkatkan level keahlian）" },
  { id: 1435, category: "setsubi_kougu", source: "vocab-jac", furi: "しつがいき", jp: "室外機", type: "vocab", id_text: "Unit luar AC / outdoor", desc: "Berisi kompresor dan kondenser; membuang panas ke luar.\nLokasi pemasangan harus" },
  { id: 1436, category: "haikan", source: "vocab-jac", furi: "しつないき", jp: "室内機", type: "vocab", id_text: "Unit dalam AC / indoor", desc: "Berisi evaporator dan kipas; mendinginkan ruangan melalui evaporasi refrigeran." },
  { id: 1437, category: "haikan", source: "vocab-jac", furi: "ふれあかこう", jp: "フレア加工", type: "vocab", id_text: "Flare processing ujung", desc: "Mengembangkan ujung pipa tembaga dengan flare tool sebelum disambung.", usage: "フレア加工《かこう》する（memproses ujung pipa tembaga menjadi flare）" },
  { id: 1438, category: "haikan", source: "vocab-jac", furi: "どれんはいかん", jp: "ドレン配管", type: "vocab", id_text: "Pipa drain AC", desc: "Mengalirkan air kondensasi dari unit dalam ke luar.\nWajib kemiringan turun" }
